def test_all(table: Table, mock_response_list, mock_records):
    with Mocker() as mock:
        mock.get(table.url, status_code=200, json=mock_response_list[0], complete_qs=True)
        for (n, resp) in enumerate(mock_response_list, 1):
            offset = resp.get('offset', None)
            if not offset:
                continue
            offset_url = table.url + '?offset={}'.format(offset)
            mock.get(offset_url, status_code=200, json=mock_response_list[1], complete_qs=True)
        response = table.all()
    for (n, resp) in enumerate(response):
        assert dict_equals(resp, {'createdTime': mock_records[n]['createdTime'], 'id': mock_records[n]['id'], 'fields': {}})"

