@pytest.mark.parametrize('container', [list, tuple, iter])
def test_batch_delete(table: Table, container, mock_records):
    ids = [i['id'] for i in mock_records]
    with Mocker() as mock:
        for chunk in _chunk(ids, 10):
            json_response = {'records': [{'deleted': False, 'id': id_} for id_ in chunk]}
            url_match = Request('get', table.url, params={'records[]': chunk}).prepare().url
            mock.delete(url_match, status_code=201, json=json_response)
        resp = table.batch_delete(container(ids))
    expected = [{'deleted': False, 'id': i} for i in ids]
    assert resp == expected"

