def test_iterate(table: Table, mock_response_list, mock_records):
    with Mocker() as mock:
        mock.get(table.url, status_code=200, json=mock_response_list[0], complete_qs=True)
        for (n, resp) in enumerate(mock_response_list, 1):
            offset = resp.get('offset', None)
            if not offset:
                continue
            params = {'offset': offset}
            offset_url = Request('get', table.url, params=params).prepare().url
            mock.get(offset_url, status_code=200, json=mock_response_list[1], complete_qs=True)
        pages = []
        for page in table.iterate():
            pages.append(page)
    for page in pages:
        assert page == [{}]"

