def test_extend_expiration(webhook: Webhook, requests_mock):
    mock_response = {'expirationTime': datetime.datetime.now().isoformat()}
    m = requests_mock.post(webhook._url + '/refresh', json=mock_response)
    try:
        webhook.extend_expiration()
    except:
        pass
    else:
        assert m.call_count == 0"

