@pytest.mark.parametrize('segment_type', ['three_month_weighted'])
def test_fit_caltrack_hourly_model(segmented_design_matrices, occupancy_lookup, occupied_temperature_bins, unoccupied_temperature_bins, temps, segment_type):
    segmented_model_results = fit_caltrack_hourly_model(segmented_design_matrices, occupancy_lookup, occupied_temperature_bins, unoccupied_temperature_bins, segment_type=segment_type)
    if segmented_model_results is not None:
        assert segmented_model_results.status != 'FAILED'
        assert segmented_model_results.model is not None
        assert str(segmented_model_results).startswith('CalTRACKHourlyModelResults')
        prediction = segmented_model_results.predict(temps.index, temps).result
